# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÖZ DENETİM (OTOKONTROL), İHSAN BİLİNCİ VE TAKVA AHLAKI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Öz Denetim (Nefis Muhasebesi)</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• Kişinin hiç kimsenin görmediği yerde bile</text>\n  <text x="54" y="116" font-size="11" fill="#334155">Allah\'ın kendisini gördüğünü bilerek</text>\n  <text x="54" y="132" font-size="11" fill="#334155">söz ve davranışlarını kontrol etmesidir.</text>\n  <text x="44" y="156" font-size="11.5" fill="#334155">• Öfkeyi yenmek: "Güçlü kimse güreşte</text>\n  <text x="54" y="172" font-size="11" fill="#334155">yenen değil, öfke anında nefsine</text>\n  <text x="54" y="188" font-size="11" fill="#334155">hâkim olandır." (Hadis-i Şerif)</text>\n  <text x="183" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Duygu · Düşünce · Davranış Kontrolü</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. İhsan ve Murakabe Bilinci</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• İhsan: "Allah\'ı görüyormuşçasına O\'na</text>\n  <text x="388" y="116" font-size="11" fill="#334155">kulluk etmendir; sen O\'nu görmesen de</text>\n  <text x="388" y="132" font-size="11" fill="#334155">O seni görmektedir." (Cibril Hadisi)</text>\n  <text x="378" y="156" font-size="11.5" fill="#334155">• Kâf Suresi 18. Ayet: Kirâmen Kâtibîn</text>\n  <text x="388" y="172" font-size="11" fill="#334155">meleklerinin her söz ve ameli kaydetmesi.</text>\n  <text x="378" y="196" font-size="11.5" fill="#334155">• Hucurât, 12: Zan, tecessüs ve gıybetten sakınma.</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Takva · İhlas · Sorumluluk Bilinci</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SABIR VE ŞÜKÜR AHLAKI: MÜMİNİN İKİ KANADI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Sabır Ahlakı ve Üç Boyutu</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• Musibetlere Sabır: Hastalık, kayıp ve</text>\n  <text x="54" y="116" font-size="11" fill="#475569">sıkıntılar karşısında metanetli olmak.</text>\n  <text x="44" y="140" font-size="11.5" fill="#334155">• İbadete (Taate) Sabır: Namaz, oruç ve</text>\n  <text x="54" y="156" font-size="11" fill="#475569">iyilikleri devamlı ve kararlılıkla yapmak.</text>\n  <text x="44" y="180" font-size="11.5" fill="#334155">• Günaha Karşı Sabır: Haram ve kötülük</text>\n  <text x="54" y="196" font-size="11" fill="#475569">çekiciliğine karşı nefsi dizginlemek.</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">"Şüphesiz Allah sabredenlerle beraberdir." (Bakara, 153)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Şükür Ahlakı (Kalp, Dil ve Davranış)</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• Kalp ile Şükür: Nimetlerin gerçek sahibinin</text>\n  <text x="388" y="116" font-size="11" fill="#475569">Yüce Allah olduğunu gönülden bilmek.</text>\n  <text x="378" y="140" font-size="11.5" fill="#334155">• Dil ile Şükür: "Elhamdülillâh" diyerek</text>\n  <text x="388" y="156" font-size="11" fill="#475569">Allah\'a hamd ve insanlara teşekkür etmek.</text>\n  <text x="378" y="180" font-size="11.5" fill="#334155">• Beden ve Mal ile Şükür: Nimeti helal yolda</text>\n  <text x="388" y="196" font-size="11" fill="#475569">kullanmak, israf etmemek ve infak etmek.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">"Şükrederseniz nimetimi artırırım." (İbrahim, 7)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HOŞGÖRÜ (MÜSAMAHA), AFFEDİCİLİK VE KARDEŞLİK AHLAKI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. Hoşgörü (Müsamaha) ve Rıfk</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• Farklı düşünce ve hataları nezaketle,</text>\n  <text x="54" y="116" font-size="11" fill="#334155">anlayışla ve yumuşak huyla (rıfk) karşılamak.</text>\n  <text x="44" y="140" font-size="11.5" fill="#334155">• "Kolaylaştırınız, zorlaştırmayınız;</text>\n  <text x="54" y="156" font-size="11" fill="#334155">müjdeleyiniz, nefret ettirmeyiniz." (Hadis)</text>\n  <text x="44" y="180" font-size="11.5" fill="#334155">• Kusurları örtmek (Setr-i Uyûb) ve</text>\n  <text x="54" y="196" font-size="11" fill="#334155">insanlara hüsnüzan (iyi niyet) beslemek.</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Yumuşak Huyluluk (Hilm ve Rıfk)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">2. Affedicilik (Afv ve Safh)</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• Âl-i İmrân, 134: "Onlar öfkelerini</text>\n  <text x="388" y="116" font-size="11" fill="#334155">yutarlar ve insanları affederler."</text>\n  <text x="378" y="140" font-size="11.5" fill="#334155">• Hz. Peygamber\'in Taif\'te ve Mekke\'nin</text>\n  <text x="388" y="156" font-size="11" fill="#334155">Fethi\'nde (630) düşmanlarını bağışlaması.</text>\n  <text x="378" y="180" font-size="11.5" fill="#334155">• Hz. Yusuf\'un kardeşlerine: "Bugün size</text>\n  <text x="388" y="196" font-size="11" fill="#334155">kınama yoktur, Allah sizi bağışlasın" demesi.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Kin ve İntikam Yerine Barış ve Af</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
